# tiny unifier: type terms + union-find + occurs check
parent = {}

def find(t):
    while isinstance(t, str) and t in parent:
        t = parent[t]
    return t

def occurs(v, t):
    t = find(t)
    if t == v:
        return True
    return isinstance(t, tuple) and any(occurs(v, s) for s in t[1:])

def unify(a, b):
    a, b = find(a), find(b)
    if a == b:
        return True
    if isinstance(a, str):
        if occurs(a, b):
            return False  # infinite type rejected
        parent[a] = b
        return True
    if isinstance(b, str):
        return unify(b, a)
    return (isinstance(a, tuple) and isinstance(b, tuple) and a[0] == b[0]
            and len(a) == len(b) and all(unify(x, y) for x, y in zip(a[1:], b[1:])))

print(unify('t1', ('List', 't2')), unify('t1', ('List', int)))
print('t2 =', find('t2'), '(propagated through t1)')
parent.clear()
print('t = List[t] :', unify('t', ('List', 't')), '(occurs check rejects)')

# constraints: t_arg <: t_param, then solve by propagation
# lattice: int <: float, str unrelated
SUPER = {'int': 'float', 'float': 'object', 'str': 'object', 'object': None}

def is_sub(a, b):
    while a is not None:
        if a == b:
            return True
        a = SUPER.get(a)
    return False

constraints = [('t_arg', '<:', 't_param')]  # from a call f(x: int) where param: float
solution = {'t_arg': 'int', 't_param': 'float'}
ok = all(is_sub(solution[a], solution[b]) for a, _, b in constraints)
print('constraints:', constraints)
print('solution:', solution, '-> satisfied:', ok)
constraints.append(('t_bad', '<:', 't_param2'))
print('conflicting constraints become the error message (with provenance)')

# infer T from arguments: first([1,2,3]) -> T = int
def infer_call(param_T, args):
    bindings = {}
    for a in args:
        t = type(a).__name__
        if param_T in bindings and bindings[param_T] != t:
            return 'ERROR: T inferred as both %s and %s' % (bindings[param_T], t)
        bindings[param_T] = t
    return bindings

print('first([1,2,3]):', infer_call('T', [[1, 2, 3]]), '-> element type int')
print('pair(1, "a"):', infer_call('T', [1, 'a']))
print('no annotations at the call site: T solved from the arguments')
